74	export const getArticles = async (query: any, id?: number) => {
75	  const andQueries = buildFindAllQuery(query, id);
76	  const articlesCount = await prisma.article.count({
77	    where: {
78	      AND: andQueries,
79	    },
80	  });
81	
82	  const articles = await prisma.article.findMany({
83	    where: { AND: andQueries },
84	    orderBy: {
85	      createdAt: 'desc',
86	    },
87	    skip: Number(query.offset) || 0,
88	    take: Math.min(Number(query.limit) || ARTICLE_LIST_DEFAULT_LIMIT, ARTICLE_LIST_MAX_LIMIT),
89	    include: {
90	      tagList: {
91	        select: {
92	          name: true,
93	        },
94	      },
95	      author: {
96	        select: {
97	          username: true,
