167	export const createArticle = async (article: any, id: number) => {
168	  const { title, description, body, tagList } = article;
169	  const tags = Array.isArray(tagList) ? tagList : [];
170	
171	  if (!title) {
172	    throw new HttpException(422, { errors: { title: ["can't be blank"] } });
173	  }
174	
175	  if (!description) {
176	    throw new HttpException(422, { errors: { description: ["can't be blank"] } });
