202	  } = await prisma.article.create({
203	    data: {
204	      title,
205	      description,
206	      body,
207	      slug,
208	      tagList: {
209	        connectOrCreate: tags.map((tag: string) => ({
210	          create: { name: tag },
211	          where: { name: tag },
212	        })),
213	      },
214	      author: {
215	        connect: {
216	          id: id,
217	        },
218	      },
219	    },
220	    include: {
221	      tagList: {
222	        select: {
223	          name: true,
224	        },
